    localparam IDLE=0, KEY0=1, KEY1=2, SUB=3, SHIFT=4, COL=5, DONE=6;
    reg [2:0] st;
    reg [127:0] state_reg, round_key, output_reg, cache_input, cache_last;
    reg cache_valid, decrypt, warmup;
    reg [15:0] subword;
    reg [3:0] round_cnt;
    reg [2:0] sub_cnt;
    reg [1:0] col_cnt;
    reg [7:0] rcon;
